/**
 * AUTO-GENERATED - Embedded WOFF fonts for Satori rendering.
 * Self-contained base64 strings so rendering works in both local dev and Vercel Serverless
 * without runtime filesystem dependencies.
 */

export const newsreaderRegularBase64 = "";
export const newsreaderRegularMeta = { name: "Newsreader", weight: 400, style: "normal" as const };

export const newsreaderBoldBase64 = "";
export const newsreaderBoldMeta = { name: "Newsreader", weight: 700, style: "normal" as const };

export const newsreaderItalicBase64 = "";
export const newsreaderItalicMeta = { name: "Newsreader", weight: 400, style: "italic" as const };

export const interRegularBase64 = "";
export const interRegularMeta = { name: "Inter", weight: 400, style: "normal" as const };

export const interBoldBase64 = "";
export const interBoldMeta = { name: "Inter", weight: 700, style: "normal" as const };

export function getSatoriFonts() {
  return [
    { ...newsreaderRegularMeta, data: Buffer.from(newsreaderRegularBase64, "base64") },
    { ...newsreaderBoldMeta, data: Buffer.from(newsreaderBoldBase64, "base64") },
    { ...newsreaderItalicMeta, data: Buffer.from(newsreaderItalicBase64, "base64") },
    { ...interRegularMeta, data: Buffer.from(interRegularBase64, "base64") },
    { ...interBoldMeta, data: Buffer.from(interBoldBase64, "base64") },
  ];
}
